#!/usr/bin/env node
"use strict";
// The onboarding PR's body (onboard.yml), from the generated files on this checkout. Plain code.
//   node onboard/summary.js <code>
const fs = require("fs");
const path = require("path");
const YAML = require("yaml");
const LOCALES = require("../lib/locales");

const REPO = path.resolve(__dirname, "../..");
const code = process.argv[2];
const locale = LOCALES.generatedLocales(REPO).find((l) => l.code === code);
if (!locale) {
    console.error(`${code} is not a generated locale on this checkout`);
    process.exit(1);
}
const fragment = YAML.parse(fs.readFileSync(path.join(REPO, `scripts/seed-backlog/taskmap.d/${locale.module}.yaml`), "utf8"));
const contracts = fragment.tasks.map((t) => YAML.parse(fs.readFileSync(path.join(REPO, `contracts/${t.id}.yaml`), "utf8")));
const index = JSON.parse(fs.readFileSync(path.join(REPO, "tests/golden/index.json"), "utf8")).files;
const areas = Object.entries(index).filter(([a]) => a.startsWith(`${locale.module}/`));
const golden = areas.reduce((n, [, f]) => n + f.cases, 0);
const coverage = areas.filter(([a]) => a === `${locale.module}/coverage`).reduce((n, [, f]) => n + f.cases, 0);
const tiers = {};
for (const c of contracts) tiers[c.tier] = (tiers[c.tier] || 0) + 1;
const ready = contracts.filter((c) => c.depends_on.length === 0).length;

const lines = [
    `Onboards \`${code}\` (upstream \`src/${locale.upstream}\`) with no hand-written setup: everything here is generator output (\`harness/onboard/onboard.js add ${code}\`, plain code, no AI).`,
    `${contracts.length} tasks (${Object.entries(tiers).map(([t, n]) => `${n} ${t}`).join(", ")}); ${golden} golden cases recorded from the pinned chrono-node${coverage ? ` (${coverage} of them coverage requests for steps no upstream test reaches)` : ""}.`,
    "CI regenerates every file byte for byte from `upstream/` (`golden:check`, `onboard.js check`, `seed.js contracts --check`). Existing contracts and golden files are unchanged; only the two golden indexes gain this locale's entries.",
    `After merge, \`onboard.yml\` creates the task issues; ${ready} can start at once and the controller's auto-ready dispatches the auto-tier ones.`,
    "",
    "## Tasks",
    "| Task | Tier | Area | Depends on | Golden cases | Acceptance |",
    "|---|---|---|---|---|---|",
    ...contracts.map((c) => {
        const acc = c.acceptance.map((a) => Object.keys(a)[0]).filter((k) => !["clippy", "public_api"].includes(k));
        const unit = (c.acceptance.find((a) => a.unit) || {}).unit;
        return `| ${c.id} | ${c.tier} | ${c.area} | ${c.depends_on.length ? c.depends_on.join(", ") : "none"} | ${c.golden_cases} | ${acc.join(", ")}${unit ? ` (${unit.cases.length} cases)` : ""} |`;
    }),
    "",
    "## Generated files",
    `- \`src/locales/${locale.module}/locale.json\`, \`mod.rs\`, \`configuration.rs\`: manifest and the named configurations' slots (${Object.keys(locale.configs).join(", ")})`,
    `- \`tests/golden/${locale.module}/\`: ${areas.length} areas; \`tests/golden/index.json\`, \`configurations.json\`: this locale's entries added`,
    ...(coverage ? [`- \`harness/golden/coverage/${locale.module}.json\`: the coverage requests (the comparison's golden-text phrases, fixed seed)`] : []),
    `- \`scripts/seed-backlog/taskmap.d/${locale.module}.yaml\` and \`contracts/${code}/\`: the task map fragment and its contracts`,
    "",
    "## Journal",
    `- Generated by the onboarding pipeline; the only input is the language code \`${code}\`. Tiers come from factory \`policies/tiers.yaml\`, so a support file outside every tier (\`constants.rs\`) is human tier (fail closed).`,
];
console.log(lines.join("\n"));
